from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class BotsMethods(BaseClient):
    """
    Методы группы 'Для ботов' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("bots.rapi_getBotCallbackAnswer")
    def rapi_getBotCallbackAnswer(self, chatId: str, msgId: str, callbackData: str) -> dict:
        """
        Уведомляем бота о нажатии на кнопку

        :param chatId: ID чата
        :param msgId: ID сообщения
        :param callbackData: текст callback'a
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/getBotCallbackAnswer",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "chatId": chatId,
                    "msgId": msgId,
                    "callbackData": callbackData,
                },
            },
        )

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("bots.rapi_startBot")
    def rapi_startBot(self, bot: str, startParameter: str) -> dict:
        """
        Передаем боту на старте доп параметр
        :param bot: ID бота
        :param startParameter: параметр
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/startBot",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"bot": bot, "startParameter": startParameter},
            },
        )
